// Clean-room TSVC s115 profile; see package rights note.
fn put64(o:[*]u8,p:usize,v:i64)void{const b=@as(u64,@bitCast(v));for(0..8)|k|o[p+k]=@truncate(b>>(8*k));}
pub export fn tsvc_s115_upper_triangular_saxpy_elimination(input:?[*]const i64,length:usize,output:?[*]u8,capacity:usize)i64{if(input==null or length<8 or length>58)return -1;const v=input.?[0..length];if(v[0]<2 or v[0]>7 or v[1]<1 or v[1]>3)return -1;const n:usize=@intCast(v[0]);const passes:usize=@intCast(v[1]);if(length!=2+n+n*n)return -1;var a=[_]i64{0}**8;var m=[_]i64{0}**64;for(0..n)|i|{const x=v[2+i];if(x< -1 or x>1)return -1;a[i]=x;}for(0..n*n)|i|{const x=v[2+n+i];if(x< -1 or x>1)return -1;m[i]=x;}if(output==null or capacity<8*n)return -2;for(0..passes)|_|{for(0..n)|j|{for(j+1..n)|i|{a[i]-=m[j*n+i]*a[j];}}}for(0..n)|i|put64(output.?,8*i,a[i]);return @intCast(n);}
